"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    # Ensure exact prefix match to prevent leakage of administrative events
    if subscribed_pattern == event_topic:
        return True
    # For wildcard patterns, allow prefix matching
    if subscribed_pattern.endswith("*"):
        return event_topic.startswith(subscribed_pattern.rstrip("*"))
    # For exact match patterns, require exact string equality
    return event_topic == subscribed_pattern

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
=== END ===
